Procedure DFS; (Depth First Search)
Begin
    Push (MO,nₒ)
    DONG=null;
    While MO<> null do
        begin
            n:=pop (MO);
            if n ∈ DICH then exit;
            push (DONG, n);
            For m ∈ T(n) and m∉DONG+MO do
                Push (MO, m);
            end;
